window.DP_INTERVIEW.questions.push(
  {q:"Output? def f(x=[]): x.append(1); return x — print(f()); print(f())",level:"Output-Based",difficulty:"Advanced",experience:"2-6 Years",company:["Google","Amazon","Meta"],answer:"[1] then [1, 1]. The default list is created ONCE and SHARED across calls. Mutable defaults trap.",code:`def f(x=[]): x.append(1); return x\nprint(f()); print(f())`,output:`[1]\n[1, 1]`,tips:"Never use mutable defaults — famous Python gotcha."},
  {q:"Output? print([lambda x: x*i for i in range(3)][0](10))",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta"],answer:"20. Lambdas capture i by REFERENCE. By the time the lambda is called, the loop has finished and i=2. So all lambdas multiply by 2, and 10*2=20.",code:`fs=[lambda x: x*i for i in range(3)]\nprint(fs[0](10))`,output:`20`,tips:"Late binding trap — fix with lambda x, i=i: x*i."},
  {q:"Output? print(bool(bool(bool(''))))",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Zoho"],answer:"False. bool('')=False, bool(False)=False, bool(False)=False. Nested bool doesn't change a False.",code:`print(bool(bool(bool(''))))`,output:`False`,tips:"Empty string is falsy; bool() is idempotent."},
  {q:"Output? print(2 * (3 * 'ab'))",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Zoho"],answer:"'ababababababab'. 3*'ab'='ababab' (6 chars), then 2*'ababab'='ababababababab' (12 chars).",code:`print(2 * (3 * 'ab'))`,output:`ababababababab`,tips:"String multiplication distributes over left/right."},
  {q:"Output? a=b=[1,2]; a.append(3); print(b)",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Adobe","Meta"],answer:"[1, 2, 3]. Chained assignment binds BOTH names to the SAME list object. Modifying via a affects b.",code:`a=b=[1,2]; a.append(3); print(b)`,output:`[1, 2, 3]`,tips:"Chained assignment shares reference — not a copy."},
  {q:"Output? print([1,2,3][::-2])",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"[3, 1]. Step -2 reverses and takes every other: index 2 (=3), then 0 (=1).",code:`print([1,2,3][::-2])`,output:`[3, 1]`,tips:"Negative step reverses; step size skips elements."},
  {q:"Output? print(sum([True, True, False, True]))",level:"Output-Based",difficulty:"Beginner",experience:"1-4 Years",company:["Amazon","Adobe"],answer:"3. Booleans are ints: True=1, False=0. sum([1,1,0,1])=3.",code:`print(sum([True, True, False, True]))`,output:`3`,tips:"Common pattern: sum(condition for x in ...) counts matches."},
  {q:"Output? print('abc' > 'ab')",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"True. Lexicographic: matching prefix, then longer string wins.",code:`print('abc' > 'ab')`,output:`True`,tips:"String order = char-by-char comparison + length tiebreak."},
  {q:"Output? print(1 + True + None)",level:"Output-Based",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Adobe"],answer:"TypeError: unsupported operand for +: int and NoneType. 1+True=2 (True is int), but 2+None fails.",code:`print(1 + True + None)  # TypeError`,output:`TypeError`,tips:"None is not numeric — cannot add."},
  {q:"Output? x=(1,2,3); x+=(4,); print(x)",level:"Output-Based",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Adobe","Google"],answer:"(1, 2, 3, 4). Tuples are immutable, so += creates a NEW tuple and rebinds x. Not the same as list += (which mutates).",code:`x=(1,2,3); x+=(4,); print(x)`,output:`(1, 2, 3, 4)`,tips:"+= on immutables rebinds; on mutables mutates in place."},
  {q:"Output? t=([1,2],3); t[0].append(9); print(t)",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta","Amazon"],answer:"([1, 2, 9], 3). Tuple is immutable but the inner LIST is mutable — you can modify contents of a mutable inside an immutable container.",code:`t=([1,2],3); t[0].append(9); print(t)`,output:`([1, 2, 9], 3)`,tips:"Immutable containers can hold mutable objects — famous gotcha."},
  {q:"Output? print(3 * [0])",level:"Output-Based",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho"],answer:"[0, 0, 0]. int * list repeats the list.",code:`print(3 * [0])`,output:`[0, 0, 0]`,tips:"Great way to init a list of zeros."},
  {q:"Output? grid=[[0]*3]*3; grid[0][0]=1; print(grid)",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta","Amazon"],answer:"[[1, 0, 0], [1, 0, 0], [1, 0, 0]]. All three rows are the SAME list — modifying one changes all. Fix: [[0]*3 for _ in range(3)].",code:`grid=[[0]*3]*3; grid[0][0]=1; print(grid)`,output:`[[1, 0, 0], [1, 0, 0], [1, 0, 0]]`,tips:"NEVER use * for nested lists — use comprehension."},
  {q:"Output? print(' '.join(['a','b','c']))",level:"Output-Based",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho","TCS"],answer:"'a b c'. join inserts the separator between each element.",code:`print(' '.join(['a','b','c']))`,output:`a b c`,tips:"str.join(iterable) — separator becomes 'this string'."},
  {q:"Output? print({True: 'a', 1: 'b', 1.0: 'c'})",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta"],answer:"{True: 'c'}. In Python, True==1==1.0 and they hash equally, so they're treated as the SAME dict key. Only the last value wins.",code:`print({True: 'a', 1: 'b', 1.0: 'c'})`,output:`{True: 'c'}`,tips:"Dict keys use hash() and ==. Boolean is int — beware."},
  {q:"Output? print(sorted(['banana','apple','cherry'], key=len))",level:"Output-Based",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google","Adobe"],answer:"['apple', 'banana', 'cherry']. Sort by length: 5, 6, 6. Timsort is stable, so equal-length items keep original order.",code:`print(sorted(['banana','apple','cherry'], key=len))`,output:`['apple', 'banana', 'cherry']`,tips:"Timsort preserves relative order of equal keys (stable)."},
  {q:"Output? a=1; b=1; print(a is b); a=1000; b=1000; print(a is b)",level:"Output-Based",difficulty:"Expert",experience:"3-7 Years",company:["Google","Meta","Amazon"],answer:"True (usually), then False (usually). Small ints -5..256 are cached; larger ints are separate objects. Implementation detail — never rely on this.",code:`a=1000; b=1000\nprint(a is b)  # usually False in script`,output:`False`,tips:"Small-int cache is a CPython optimization, not a guarantee."},
  {q:"Output? print(list(map(pow, [2,3,4], [3,2,1])))",level:"Output-Based",difficulty:"Advanced",experience:"2-6 Years",company:["Google","Amazon"],answer:"[8, 9, 4]. map with multiple iterables passes one from each: pow(2,3)=8, pow(3,2)=9, pow(4,1)=4.",code:`print(list(map(pow, [2,3,4], [3,2,1])))`,output:`[8, 9, 4]`,tips:"map accepts multiple iterables — zipped into function args."},
  {q:"Output? print([] == [])",level:"Output-Based",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho"],answer:"True. Two empty lists are equal in value. However [] is [] would be False (different objects).",code:`print([] == [], [] is [])`,output:`True False`,tips:"== compares value; is compares identity."},
  {q:"Output? print(bool('False'), bool([False]), bool(0.0), bool(0j))",level:"Output-Based",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google","Adobe"],answer:"True True False False. Non-empty string 'False'=truthy. Non-empty list [False]=truthy (containers only care if empty). 0.0 and 0j=falsy.",code:`print(bool('False'), bool([False]), bool(0.0), bool(0j))`,output:`True True False False`,tips:"Truthiness: containers care about emptiness, not contents."},
  {q:"Output? d={}; d[True]=1; d[1.0]=2; d[1]=3; print(d)",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta"],answer:"{True: 3}. True, 1.0, and 1 are all the same key (hash and equal). Only ONE entry survives; the last assignment wins.",code:`d={}; d[True]=1; d[1.0]=2; d[1]=3; print(d)`,output:`{True: 3}`,tips:"Dict key identity uses hash + eq; keeps FIRST inserted key form."},
  {q:"Output? print('a'.join(['b','c','d']))",level:"Output-Based",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho"],answer:"'bacad'. The separator 'a' is placed BETWEEN each element.",code:`print('a'.join(['b','c','d']))`,output:`bacad`,tips:"str.join uses the STRING as separator — easy to invert."},
  {q:"Output? print(1==1==True)",level:"Output-Based",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google"],answer:"True. Chained: (1==1) and (1==True). Both are True (True==1 numerically), so True.",code:`print(1==1==True)`,output:`True`,tips:"Chained comparisons evaluate left-to-right with AND semantics."},
  {q:"Output? print('py' * 0 or 'default')",level:"Output-Based",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"'default'. 'py'*0='' (empty, falsy), so or returns the second operand.",code:`print('py' * 0 or 'default')`,output:`default`,tips:"'or' is a common default-value idiom."},
  {q:"Output? nums=[1,2,3]; print([nums.pop() for _ in nums])",level:"Output-Based",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta"],answer:"[3, 2]. The comprehension iterates while mutating the source — dangerous. It sees length change as it pops. Never mutate the iterable you're iterating.",code:`nums=[1,2,3]; print([nums.pop() for _ in nums])`,output:`[3, 2]`,tips:"Never mutate the collection you're iterating."}
);


