window.DP_INTERVIEW.questions.push(
  {q:"[LinkedIn] Design a 'People You May Know' feature.",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["LinkedIn","Meta"],answer:"For each user, compute friends-of-friends (2-hop) from the social graph. Score by: mutual connections, shared companies/schools, recent activity. Precompute daily; cache top-N per user. LinkedIn uses their Pregel-based graph engine.",tips:"2-hop BFS + scoring — classic social graph problem."},
  {q:"[LinkedIn] How would you rank a user's feed?",level:"Company-Specific",difficulty:"Expert",experience:"5-10+ Years",company:["LinkedIn","Meta","Twitter"],answer:"Multi-tier ranking: candidate generation (from followed + interests), first-pass filter (freshness, safety), heavy ranker (ML model scoring engagement probability). Diversity constraints prevent one topic dominating. A/B tested continuously.",tips:"Candidate generation -> filter -> ranker -> diversity is the standard pipeline."},
  {q:"[Twitter/X] Design a tweet fanout system.",level:"Company-Specific",difficulty:"Expert",experience:"5-10+ Years",company:["Twitter","Meta","LinkedIn"],answer:"Hybrid fanout: PUSH to followers' timelines on tweet (fast reads) for regular users; PULL from celebrity feeds on read (avoid write amplification for millions of followers). Merge sorted timelines. Cache aggressively.",tips:"Fanout-on-write for regulars + fanout-on-read for celebrities."},
  {q:"[Twitter/X] Design a trending topics system.",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Twitter","LinkedIn"],answer:"Real-time count of hashtags/keywords in a sliding window (last 1h/24h). Compare current velocity vs baseline. Use approximate structures (Count-Min Sketch, Top-K) for scale. Filter spam, geo-bucket, and cluster related topics.",tips:"Streaming + approximate counting = scalable trending."},
  {q:"[Stripe] How do you handle failed payments and retries?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Stripe","PayPal"],answer:"Categorize errors: retriable (network, temp) vs hard (declined, fraud). Exponential backoff for retriable. 'Smart Retries' analyze historical success times. Idempotency keys prevent duplicates. Notify user + suggest fix for hard failures.",tips:"Stripe's Smart Retries + idempotency is a known best practice."},
  {q:"[Stripe] How do you build a webhook system that scales?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Stripe","Shopify"],answer:"Producer sends events to a durable queue. Delivery workers pull, POST to customer URLs, retry with exponential backoff for 5xx/timeouts. Sign payloads with HMAC. Provide replay UI. Store delivery attempts for debugging.",tips:"HMAC signing + retries + replay is the industry pattern."},
  {q:"[Shopify] Design an inventory system across warehouses.",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Shopify","Amazon","Walmart Global Tech"],answer:"Table (sku, warehouse, on_hand, reserved). Use optimistic locking or DB row locks for concurrent decrements. Reserve on cart-add with expiration; commit on order. Async replicate to search index. Nightly reconciliation with physical counts.",tips:"Reservations with expiration prevent stock-holding abuse."},
  {q:"[Shopify] How would you handle Black Friday traffic spikes?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Shopify","Amazon"],answer:"Pre-scale (predictive autoscaling), CDN + edge caching, request queueing to smooth spikes, circuit breakers on downstream deps, feature-flag non-critical features, DB read replicas, static checkout landing pages. Load-test to 5x expected peak.",tips:"Shopify actually publishes their Black Friday scale numbers — reference them."},
  {q:"[Airbnb] Design a search-and-book system.",level:"Company-Specific",difficulty:"Expert",experience:"5-10+ Years",company:["Airbnb","Booking"],answer:"Elasticsearch for geo + text search with filters. Availability service (per-listing, per-date). Booking flow: lock dates -> collect payment -> confirm reservation atomically. Handle overlapping requests with optimistic concurrency.",tips:"Availability + payment atomicity is the hardest part."},
  {q:"[Airbnb] How did Airbnb build Airflow?",level:"Company-Specific",difficulty:"Advanced",experience:"3-8 Years",company:["Airbnb"],answer:"Airflow started at Airbnb (Maxime Beauchemin) to orchestrate their data pipelines. Written in Python, DAGs are Python files. Open-sourced in 2015. Now a top-level Apache project used industry-wide.",tips:"Airflow's Python-based DAGs came from Airbnb's ETL needs."},
  {q:"[Salesforce] What is Apex?",level:"Company-Specific",difficulty:"Intermediate",experience:"1-6 Years",company:["Salesforce"],answer:"Salesforce's Java-like language for custom logic on the platform. Runs on multi-tenant servers with strict governor limits (CPU, queries, heap). Used for triggers, controllers, batch jobs.",tips:"Salesforce-specific — mention governor limits to sound knowledgeable."},
  {q:"[SAP] What is ABAP?",level:"Company-Specific",difficulty:"Intermediate",experience:"1-8 Years",company:["SAP"],answer:"SAP's proprietary language for developing on SAP systems. Used for reports, transactions, and business logic. Modern SAP shifts toward Java/Node.js for new services, but ABAP is still core for on-prem ERP.",tips:"SAP legacy = ABAP; SAP HANA/Cloud = also uses Python/JS."},
  {q:"[Intel] What is SIMD and how does Python leverage it?",level:"Company-Specific",difficulty:"Expert",experience:"3-10+ Years",company:["Intel","NVIDIA","Google"],answer:"Single Instruction Multiple Data — CPU can perform one operation on multiple values in parallel (AVX, SSE). Python doesn't use SIMD directly, but NumPy/PyTorch/TensorFlow use SIMD-optimized C/CUDA underneath.",tips:"NumPy speed comes from SIMD-optimized BLAS/LAPACK libraries."},
  {q:"[NVIDIA] What is CUDA and how does PyTorch use it?",level:"Company-Specific",difficulty:"Expert",experience:"3-10+ Years",company:["NVIDIA","Google","Meta"],answer:"CUDA is NVIDIA's platform for GPU computing. PyTorch tensors on GPU (.cuda() or .to('cuda')) are backed by CUDA kernels for parallel math. Model.to('cuda') moves parameters to GPU memory for training/inference.",tips:"Show you know: tensor.to('cuda') and .cpu() basics."},
  {q:"[Databricks] What is Delta Lake?",level:"Company-Specific",difficulty:"Expert",experience:"3-8 Years",company:["Databricks","Netflix"],answer:"An open-source storage layer that brings ACID transactions, time travel, and schema enforcement to data lakes on top of Parquet files. Enables 'lakehouse' architecture — warehouse features on cheap object storage.",tips:"Delta Lake vs Iceberg vs Hudi — Databricks pushes Delta."},
  {q:"[Confluent/Kafka] What is Kafka Streams?",level:"Company-Specific",difficulty:"Expert",experience:"3-8 Years",company:["Confluent","LinkedIn","Netflix"],answer:"A Java library for building streaming apps directly on Kafka — no separate cluster. Handles state (RocksDB), windowing, joins, and exactly-once. For non-JVM stacks, use ksqlDB or Flink instead.",tips:"For Python, use Faust or move to Flink."},
  {q:"[Snowflake] Why is Snowflake fast for analytics?",level:"Company-Specific",difficulty:"Advanced",experience:"2-8 Years",company:["Snowflake","Amazon"],answer:"Separates storage (S3) from compute (virtual warehouses). Columnar storage + micro-partitions with metadata for pruning. Independent scaling of warehouses per workload. Automatic caching. Zero-copy cloning.",tips:"Storage/compute separation is Snowflake's key innovation."},
  {q:"[GitHub] Design a git hosting service.",level:"Company-Specific",difficulty:"Expert",experience:"5-10+ Years",company:["GitHub","GitLab"],answer:"Store git repos on distributed filesystem (rebalanced across nodes). Metadata in a relational DB. Read replicas for scale. Auth service. Web UI serves rendered code. Webhook system. LFS for large files. CDN for downloads.",tips:"GitHub open-sourced 'Spokes' for their git shard replication."},
  {q:"[Cloudflare] How does a CDN cache invalidation work?",level:"Company-Specific",difficulty:"Expert",experience:"3-8 Years",company:["Cloudflare","Amazon","Netflix"],answer:"Two mechanisms: TTL-based expiration (natural), and active purge (API-triggered). Purge propagates to all edge POPs via a gossip/pub-sub layer. Purge by URL, tag, or entire zone. Typical propagation: seconds.",tips:"Purge-by-tag is powerful for cache-key groups."},
  {q:"[Dropbox] How to sync files across devices efficiently?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Dropbox","Google","Apple"],answer:"Content-addressable storage: split files into 4MB blocks, hash each. Upload only changed blocks (delta sync). Clients maintain a metadata DB of blocks and paths. Server dedupes across users. Watch filesystem events for changes.",tips:"Block-level delta sync + dedup is Dropbox's core innovation."},
  {q:"[Reddit] How would you design a comment tree system?",level:"Company-Specific",difficulty:"Advanced",experience:"3-8 Years",company:["Reddit","Meta","Twitter"],answer:"Each comment has (id, parent_id, thread_id). Store as adjacency list. To read a thread, batch-fetch all comments by thread_id, then build tree in-memory. Cache rendered threads. Vote counts in a fast KV store.",tips:"Adjacency list + tree build in memory scales far."},
  {q:"[Slack] How does message delivery guarantee ordering?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Slack","Discord"],answer:"Per-channel Kafka partition (or per-channel writer) ensures ordering. Clients use WebSockets; server pushes in order. Include monotonic message_id/timestamp — clients drop out-of-order duplicates.",tips:"Partition by channel_id for ordering guarantees."},
  {q:"[Discord] Why did Discord move from MongoDB to Cassandra to ScyllaDB?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Discord"],answer:"MongoDB struggled with write scale. Cassandra handled writes but had GC/latency issues at their scale (billions of messages). ScyllaDB (C++ rewrite of Cassandra) gave better latency + lower resource usage. Well-documented migration.",tips:"Discord published this journey — a great case study."},
  {q:"[Instagram] How did Instagram scale on Django?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Meta","Instagram"],answer:"Massive Postgres sharding, aggressive caching (Memcached + Redis), Cassandra for time-series (feeds), background jobs for async work. Ran Django with Gunicorn on many boxes. Proves Python + Django can scale to billions.",tips:"Instagram is the classic 'Python scales' proof point."},
  {q:"[Spotify] How does Spotify build recommendations?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Spotify","Netflix"],answer:"Collaborative filtering + content-based (audio features) + natural language processing on blogs/reviews. Uses Word2Vec-style embeddings on user listening sequences. Ranks candidates with ML. Notable: Discover Weekly playlist.",tips:"Hybrid recommenders beat single-approach — mention it."},
  {q:"[Pinterest] How does Pinterest handle image storage?",level:"Company-Specific",difficulty:"Expert",experience:"3-8 Years",company:["Pinterest","Meta"],answer:"Original images in S3. Precomputed thumbnails at many sizes (grid, feed, mobile). CDN serves derivative sizes. Metadata in sharded MySQL. Uses ML for visual search and recommendations.",tips:"Pre-generate derivatives; never resize on-demand."},
  {q:"[Meta/Facebook] What is Cassandra's connection to Meta?",level:"Company-Specific",difficulty:"Advanced",experience:"3-8 Years",company:["Meta","Netflix","Apple"],answer:"Cassandra was originally built at Facebook for inbox search. Open-sourced in 2008. Combines Amazon Dynamo's distribution model with Google Bigtable's data model. Now widely used at Netflix, Apple, and others.",tips:"Trivia bonus — shows history knowledge."},
  {q:"[Coinbase] Design a real-time price ticker service.",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["Coinbase","Robinhood"],answer:"Ingest exchange feeds into Kafka. Aggregate to compute cross-exchange price. Publish to Redis and WebSocket subscribers. Store historical bars in a TSDB (TimescaleDB/InfluxDB). Fan-out efficiently to millions of concurrent WebSockets.",tips:"WebSocket fan-out + TSDB is the pattern for real-time finance."},
  {q:"[ByteDance/TikTok] How does the For You algorithm work?",level:"Company-Specific",difficulty:"Expert",experience:"4-10+ Years",company:["ByteDance"],answer:"Multi-model ranking: candidate generation (following, popular, similar users), heavy ranker (predicts watch time + engagement), diversity constraints, exploration/exploitation. Trained on strong signals (watch percentage, replays, shares).",tips:"Watch-time signal + tight feedback loop = TikTok's magic."},
  {q:"[Robinhood] Handle a 10x traffic spike (like GameStop).",level:"Company-Specific",difficulty:"Expert",experience:"5-10+ Years",company:["Robinhood","Coinbase"],answer:"Autoscale API layer, read replicas for market data, aggressive caching, queue-based order processing, circuit breakers for market data providers, feature flags to disable non-essential features. Increase clearing house collateral proactively.",tips:"Robinhood's 2021 incident is a well-known case study."}
);


/* ==================== BATCH: RAPID-FIRE ONE-LINERS ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"Rapid: What is PEP?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Infosys"],answer:"Python Enhancement Proposal — a design document proposing features or standards for Python (PEP 8 = style, PEP 20 = Zen).",tips:"PEP 8 (style) is the most famous."},
  {q:"Rapid: Is Python case-sensitive?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"Yes. `age` and `Age` are different identifiers.",tips:"All Python names are case-sensitive."},
  {q:"Rapid: What is the output of print(type(True))?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"<class 'bool'>. bool is a subclass of int.",tips:"bool is technically an int subclass."},
  {q:"Rapid: How to make a variable global inside a function?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"Use `global var_name` at the top of the function.",tips:"For enclosing scope, use `nonlocal` instead."},
  {q:"Rapid: Difference between .py and .pyc?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["TCS","Amazon"],answer:".py = source code. .pyc = compiled bytecode cached in __pycache__ for faster subsequent imports.",tips:".pyc is auto-managed — usually you don't touch it."},
  {q:"Rapid: What returns True: any([]) or all([])?",level:"Rapid-Fire",difficulty:"Advanced",experience:"1-5 Years",company:["Amazon","Google"],answer:"all([]) returns True (vacuous truth). any([]) returns False.",tips:"Empty collection: all=True, any=False."},
  {q:"Rapid: How to get the length of a dictionary?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"len(my_dict) returns the number of key-value pairs.",tips:"len() works on all collections."},
  {q:"Rapid: How to merge two lists?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"Use + operator (new list), .extend() (in place), or unpack: [*a, *b].",tips:"+ is clearest; extend is fastest for in-place."},
  {q:"Rapid: How to reverse a list?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho"],answer:"lst[::-1] returns a new reversed list. lst.reverse() reverses in place.",tips:"[::-1] is the Pythonic one-liner."},
  {q:"Rapid: How to iterate a dict in order?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"Python 3.7+ preserves INSERTION order by default. Use sorted(d.items()) for a sorted-key order.",tips:"Insertion order is guaranteed since Python 3.7."},
  {q:"Rapid: What is the difference between remove() and pop()?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","Zoho"],answer:"remove(value) removes first matching value. pop(index) removes and returns element at index (last by default).",tips:"remove=value, pop=index + returns."},
  {q:"Rapid: How to sort a list of tuples by 2nd element?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"sorted(lst, key=lambda x: x[1]) — or use itemgetter(1) for slight speedup.",tips:"lambda for readability, itemgetter for speed."},
  {q:"Rapid: How to make a shallow copy of a list?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"lst.copy(), lst[:], or list(lst) — all shallow.",tips:"Use copy.deepcopy() for nested structures."},
  {q:"Rapid: How do you check if a list is empty?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"if not my_list: is Pythonic. Avoid comparing to [] with ==.",tips:"`if not lst:` is preferred over `if len(lst)==0:`."},
  {q:"Rapid: How to convert a list to a string?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"''.join(list_of_strings) or ' '.join(...) with a separator.",tips:"Convert non-strings first: ' '.join(map(str, nums))."},
  {q:"Rapid: How to check if a string is numeric?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"s.isdigit() for digits only. For floats/negatives, try/except with float(s).",tips:"isdigit() fails on '3.14' and '-5' — use try/float."},
  {q:"Rapid: What is a set literal?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"{1, 2, 3} — curly braces WITH elements. {} is an EMPTY DICT, not empty set — use set() for that.",tips:"Empty set = set(), not {}."},
  {q:"Rapid: Difference between shallow copy and slicing [:]?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Adobe"],answer:"Same for flat lists. [:] is more implicit; .copy() is clearer. Both are shallow — nested objects are still shared.",tips:"Same for flat lists; both are shallow."},
  {q:"Rapid: How to count occurrences of an element?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","Zoho"],answer:"list.count(x) for a single element. Counter(list) for all.",tips:"Counter for multiple elements — one pass."},
  {q:"Rapid: What does *args mean in a function signature?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"Collects variable positional args into a tuple.",tips:"**kwargs collects keyword args into a dict."},
  {q:"Rapid: How to reverse a string?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"s[::-1] returns a new reversed string.",tips:"Same slicing trick as lists."},
  {q:"Rapid: Difference between iter() and next()?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"iter(x) returns an iterator from an iterable. next(it) returns the next value or raises StopIteration.",tips:"iter creates, next advances."},
  {q:"Rapid: What is __init__.py?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["TCS","Amazon"],answer:"Marks a directory as a Python package. Can be empty or run package-init code. Optional in Python 3.3+ (implicit namespace packages).",tips:"Optional in modern Python but common for explicit packages."},
  {q:"Rapid: How to write to stderr?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"import sys; print('msg', file=sys.stderr).",tips:"Use logging instead of raw stderr in real code."},
  {q:"Rapid: How to handle infinite recursion?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"Fix the base case. Increase limit with sys.setrecursionlimit(n) if truly needed (rare). Prefer iterative solutions.",tips:"Default recursion limit is 1000."},
  {q:"Rapid: What is a Python module vs a package?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["TCS","Amazon"],answer:"Module = single .py file. Package = directory of modules (with or without __init__.py).",tips:"Module=file, Package=folder."},
  {q:"Rapid: How to install a Python package?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Startups"],answer:"pip install package_name. Use pip install -r requirements.txt for a list.",tips:"Prefer pip install inside a virtualenv."},
  {q:"Rapid: What is pip?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Startups"],answer:"Python's package installer. Installs from PyPI. Modern alternative: uv (Rust-based, much faster).",tips:"pip is the standard; uv is 10-100x faster."},
  {q:"Rapid: How to create a virtual environment?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Startups"],answer:"python -m venv env, then activate: `source env/bin/activate` (Linux/Mac) or `env\\Scripts\\activate` (Windows).",tips:"Always use a virtualenv — never install packages globally."},
  {q:"Rapid: What is __main__ in Python?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"The name of the top-level script being run. Enables `if __name__=='__main__':` guard for reusable modules.",tips:"Guard runs code only when file is executed directly."},
  {q:"Rapid: How to time a function?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Google","Amazon"],answer:"time.perf_counter() before/after. For accuracy on small snippets, use timeit.timeit().",tips:"timeit runs many times for reliable measurements."},
  {q:"Rapid: How to profile a Python script?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Google","Amazon","Netflix"],answer:"python -m cProfile script.py. View results with snakeviz or pstats. Line-level: line_profiler.",tips:"cProfile for function-level; line_profiler for line-level."},
  {q:"Rapid: How to catch all exceptions?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"except Exception as e: (catches all except system-exit like KeyboardInterrupt). Avoid bare `except:`.",tips:"Exception (not BaseException) is the safe blanket."},
  {q:"Rapid: How to reraise an exception?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google"],answer:"Bare `raise` inside except reraises the current exception, preserving the traceback.",tips:"Never lose the stack trace — use bare `raise`."},
  {q:"Rapid: Difference between generator function and generator expression?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google"],answer:"Function uses `yield`; expression uses `(x for x in iter)`. Both produce generators; expressions are shorter for simple cases.",tips:"Same result, different syntax."},
  {q:"Rapid: How to check Python version?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Startups"],answer:"python --version in shell, or `import sys; print(sys.version)` in code.",tips:"sys.version_info for tuple comparisons."},
  {q:"Rapid: What is None in Python?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Amazon"],answer:"Python's null value — represents absence of a value. Singleton (only one None). Always compare with `is None`.",tips:"Never use == to compare None."},
  {q:"Rapid: What are the two types of loops in Python?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Zoho"],answer:"for (over iterables) and while (while condition true). No do-while in Python.",tips:"Python has NO do-while loop."},
  {q:"Rapid: How to use enumerate with a start index?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"enumerate(iterable, start=1) — starts index at 1 instead of 0.",tips:"Useful for 1-based numbering in output."},
  {q:"Rapid: How to unpack a dict into function args?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Google"],answer:"func(**my_dict) — each key becomes a keyword argument.",tips:"Also **kwargs to collect them inside a function."},
  {q:"Rapid: What is the ternary in Python?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"value = a if condition else b. Note: no `?:` operator.",tips:"Different syntax from C/Java — value then condition."},
  {q:"Rapid: How to check if a file exists?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"import os; os.path.exists(path) or pathlib.Path(path).exists() (modern).",tips:"pathlib is the modern preferred API."},
  {q:"Rapid: How to read a JSON file?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"import json; with open('f.json') as f: data = json.load(f).",tips:"json.load reads a file; json.loads reads a string."},
  {q:"Rapid: How to get current date/time?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["Amazon","TCS"],answer:"from datetime import datetime; datetime.now(). For UTC: datetime.now(timezone.utc).",tips:"Always use timezone-aware datetimes."},
  {q:"Rapid: What is the difference between abs() and math.fabs()?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Adobe"],answer:"abs() works on int/float/complex, returns same type. math.fabs() always returns float. Use abs() by default.",tips:"abs() is more general and preserves int type."},
  {q:"Rapid: How to remove duplicates preserving order?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google","Adobe"],answer:"list(dict.fromkeys(iterable)) preserves insertion order (Py 3.7+).",tips:"set() removes duplicates but loses order."},
  {q:"Rapid: How to swap keys and values in a dict?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-4 Years",company:["Amazon","Adobe"],answer:"{v: k for k, v in d.items()}. Warning: if values are non-unique, some keys are lost.",tips:"Values must be unique + hashable."},
  {q:"Rapid: What is the difference between del and clear() for lists?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Amazon","TCS"],answer:"del lst removes the variable name. lst.clear() empties the list but the variable still exists (empty list).",tips:"del=remove name, clear=empty contents."},
  {q:"Rapid: What is __call__?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Google","Meta"],answer:"Makes an instance callable like a function: obj(). Used in class-based decorators and stateful callables.",tips:"__call__ = 'make my object act like a function'."},
  {q:"Rapid: What is the difference between raise and assert?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google"],answer:"raise explicitly throws an exception (production use). assert throws AssertionError if False — for tests/debug only, disabled by -O.",tips:"NEVER use assert for real validation."},
  {q:"Rapid: How to get the max item from a list of dicts?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Adobe"],answer:"max(list, key=lambda x: x['field']) or use operator.itemgetter('field').",tips:"key= tells max/min/sorted how to compare."},
  {q:"Rapid: How to concatenate strings efficiently in a loop?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google"],answer:"Collect in a list, then ''.join(list). Avoid += in loops — quadratic time.",tips:"+= in a loop is O(n^2); join is O(n)."},
  {q:"Rapid: How to open a file for both reading and writing?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"open(path, 'r+') for existing file, 'w+' to create/truncate, 'a+' to append+read.",tips:"'+ ' modifier adds the other mode; still need seek() correctly."},
  {q:"Rapid: What is the difference between an argument and a parameter?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Amazon"],answer:"Parameter = name in function definition. Argument = value passed at call site.",tips:"Param=definition, Arg=call site."},
  {q:"Rapid: How do you exit a Python script?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Amazon"],answer:"import sys; sys.exit(0) — 0 = success, non-zero = error. `exit()` also works interactively.",tips:"sys.exit is the scriptable version."},
  {q:"Rapid: What is a docstring convention?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-4 Years",company:["Google","Amazon"],answer:"PEP 257 — first line is a short summary. Google, NumPy, and Sphinx styles are popular for long docstrings.",tips:"Google-style docstrings are the most common in industry."},
  {q:"Rapid: What is a callable object?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"Anything you can call with (). Functions, lambdas, classes (constructor), instances with __call__ are callable. Check with callable(obj).",tips:"callable(x) returns True if x can be called."},
  {q:"Rapid: How to check if a key exists in a dict?",level:"Rapid-Fire",difficulty:"Beginner",experience:"0-3 Years",company:["TCS","Amazon"],answer:"`key in d` (Pythonic and fast). Avoid d.has_key (removed in Python 3).",tips:"`in` uses hash — O(1) lookup."},
  {q:"Rapid: What is the difference between locals() and globals()?",level:"Rapid-Fire",difficulty:"Advanced",experience:"2-6 Years",company:["Google","Amazon"],answer:"locals() = dict of local scope. globals() = dict of module scope. Both are dicts of name -> value.",tips:"Rarely needed — mostly for meta/debug tools."},
  {q:"Rapid: How to disable a warning?",level:"Rapid-Fire",difficulty:"Intermediate",experience:"1-5 Years",company:["Amazon","Google"],answer:"import warnings; warnings.filterwarnings('ignore') — globally, or context manager `warnings.catch_warnings()`.",tips:"Prefer fixing the warning over suppressing it."}
);


/* ==================== BATCH: NETWORKING ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"What happens when you type a URL and press Enter?",level:"Networking",difficulty:"Advanced",experience:"2-8 Years",company:["Google","Amazon","Meta","Microsoft"],answer:"1) DNS resolution (browser->OS->recursive->authoritative). 2) TCP handshake (SYN, SYN-ACK, ACK). 3) TLS handshake (cert, key exchange). 4) HTTP request. 5) Server processes and responds. 6) Browser parses HTML, requests assets, renders.",tips:"Classic question — cover DNS, TCP, TLS, HTTP, and rendering."},
  {q:"What is the difference between TCP and UDP?",level:"Networking",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Cisco","Google"],answer:"TCP: connection-oriented, reliable, ordered, slower (web, email). UDP: connectionless, no guarantees, fast (streaming, gaming, DNS). Choose based on reliability vs speed.",tips:"TCP=reliable, UDP=fast+lossy."},
  {q:"What is the OSI model?",level:"Networking",difficulty:"Intermediate",experience:"1-6 Years",company:["Cisco","Intel","Amazon"],answer:"7 layers: Physical, Data Link, Network (IP), Transport (TCP/UDP), Session, Presentation, Application (HTTP). Each layer abstracts the one below.",tips:"Mnemonic: Please Do Not Throw Sausage Pizza Away."},
  {q:"What is DNS and how does it work?",level:"Networking",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Cloudflare","Google"],answer:"Domain Name System maps names (example.com) to IPs. Query order: browser cache -> OS cache -> recursive resolver -> root -> TLD (.com) -> authoritative server. Cached with TTL. DoH/DoT encrypt DNS.",tips:"Hierarchical + heavily cached."},
  {q:"What are common DNS record types?",level:"Networking",difficulty:"Advanced",experience:"1-6 Years",company:["Cloudflare","Amazon","Google"],answer:"A: IPv4. AAAA: IPv6. CNAME: alias to another name. MX: mail servers. TXT: arbitrary text (SPF, verification). NS: authoritative nameservers. SOA: zone metadata.",tips:"A, AAAA, CNAME, MX, TXT are the most-asked."},
  {q:"What is the difference between HTTP/1.1, HTTP/2, and HTTP/3?",level:"Networking",difficulty:"Expert",experience:"3-8 Years",company:["Google","Cloudflare","Amazon"],answer:"HTTP/1.1: text, one request per connection (head-of-line blocking). HTTP/2: binary, multiplexed streams over one TCP connection, server push, header compression. HTTP/3: uses QUIC over UDP — no TCP HoL blocking, better mobile perf.",tips:"HTTP/3 = QUIC/UDP — fixes TCP's head-of-line blocking."},
  {q:"What is a 3-way handshake?",level:"Networking",difficulty:"Advanced",experience:"1-6 Years",company:["Cisco","Amazon","Google"],answer:"TCP connection setup: client sends SYN with seq X, server responds SYN-ACK (ack X+1, seq Y), client ACKs (ack Y+1). Both sides now have synchronized sequence numbers.",tips:"SYN -> SYN-ACK -> ACK. Memorize."},
  {q:"What is TCP congestion control?",level:"Networking",difficulty:"Expert",experience:"3-10+ Years",company:["Google","Cisco","Netflix"],answer:"Prevents overloading the network. Slow start doubles window each RTT until threshold, then linear increase. On loss (3 dup ACKs or timeout), reduce window. Algorithms: Reno, Cubic (default Linux), BBR (Google, latency-based).",tips:"BBR (Google) is modern and latency-based — cool to mention."},
  {q:"What is a socket?",level:"Networking",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Cisco","Microsoft"],answer:"An endpoint of a network connection identified by (protocol, IP, port). Two sides connect via a socket pair. Python: socket module for raw access; higher-level libs (http, requests) wrap it.",tips:"Socket = (IP, port) + protocol."},
  {q:"What is port forwarding?",level:"Networking",difficulty:"Intermediate",experience:"1-6 Years",company:["AWS","Cisco"],answer:"Router/gateway redirects traffic arriving on a specific port to a machine/port inside a private network. Used to expose internal services (e.g., home server on port 22).",tips:"NAT + port forwarding = how home routers expose services."},
  {q:"What is a proxy vs reverse proxy?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Cloudflare","Netflix"],answer:"Forward proxy: sits in front of CLIENTS (e.g., corporate proxy filtering outbound traffic). Reverse proxy: sits in front of SERVERS (e.g., nginx routing to backends, TLS termination, caching).",tips:"Forward=for clients, Reverse=for servers."},
  {q:"What is a keep-alive connection?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Cloudflare"],answer:"HTTP/1.1 default: reuse a single TCP connection for multiple requests instead of opening a new one each time. Saves TCP+TLS handshake overhead. Client sends Connection: keep-alive; server may close after Keep-Alive: timeout=N.",tips:"HTTP/2 multiplexes many requests on one connection natively."},
  {q:"What is HTTPS and how does it work?",level:"Networking",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Google","Cloudflare"],answer:"HTTP over TLS. Handshake: server presents cert (signed by a CA), client verifies, they agree on session keys (ECDHE), then encrypted communication. Provides confidentiality, integrity, and server authentication.",tips:"TLS 1.3 is the current standard; TLS 1.2 still common."},
  {q:"What is a MITM (man-in-the-middle) attack?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Google","Amazon","Cisco"],answer:"Attacker intercepts and possibly modifies traffic between client and server. Prevented by TLS with proper certificate validation (check CA chain). Public Wi-Fi + no HTTPS = classic MITM risk.",tips:"HTTPS + cert pinning is the defense."},
  {q:"What is a CDN?",level:"Networking",difficulty:"Intermediate",experience:"1-7 Years",company:["Netflix","Cloudflare","Amazon"],answer:"Content Delivery Network — caches static content at edge servers worldwide. Users get content from the nearest POP, reducing latency and origin load. Also protects against DDoS and provides TLS termination.",tips:"CDN + WAF handle most latency and volumetric attack concerns."},
  {q:"What is a VPN?",level:"Networking",difficulty:"Intermediate",experience:"1-7 Years",company:["Cisco","Amazon"],answer:"Virtual Private Network — encrypted tunnel between client and remote gateway. Extends a private network across a public one. Used for remote work, privacy, and geo-unblocking. Protocols: OpenVPN, WireGuard, IPsec.",tips:"WireGuard is the modern lightweight choice."},
  {q:"What is CORS?",level:"Networking",difficulty:"Advanced",experience:"1-6 Years",company:["Google","PayPal","Startups"],answer:"Cross-Origin Resource Sharing — browsers block cross-origin JS calls unless the server sends Access-Control-Allow-* headers. Enforced by browsers, not servers. Preflight OPTIONS request for non-simple requests.",tips:"CORS is a browser policy, not a server security measure."},
  {q:"What is the difference between GET and POST at the network level?",level:"Networking",difficulty:"Beginner",experience:"0-5 Years",company:["Amazon","TCS","PayPal"],answer:"GET: params in URL, cacheable, idempotent, safe. POST: params in body, not cached by default, may create resources, not idempotent. Both are just HTTP methods over TCP.",tips:"GET=read+cache, POST=create+body."},
  {q:"What is a WebSocket?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Meta","Uber","Netflix"],answer:"Persistent, full-duplex TCP connection between client and server after an HTTP upgrade handshake. Both sides can send anytime — ideal for chat, live updates, gaming. Alternatives: SSE (server->client only), long polling.",tips:"WebSocket = bidirectional real-time; SSE = one-way stream."},
  {q:"What is IPv4 vs IPv6?",level:"Networking",difficulty:"Intermediate",experience:"1-6 Years",company:["Cisco","Amazon","Google"],answer:"IPv4: 32-bit (~4B addresses, exhausted). IPv6: 128-bit (2^128 addresses), better routing, built-in IPsec, no NAT needed. Adoption is still gradual; dual-stack is common.",tips:"IPv4 exhausted; IPv6 is the future but rollout is slow."},
  {q:"What is a subnet mask / CIDR?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Cisco","Amazon","AWS"],answer:"Divides an IP into network and host portions. /24 = first 24 bits are network (255.255.255.0 mask, 256 addresses). Used in VPCs, security groups, and routing.",tips:"CIDR /24 = ~256 IPs, /16 = ~65k. Common in AWS VPC design."},
  {q:"What are common HTTP status codes?",level:"Networking",difficulty:"Beginner",experience:"0-5 Years",company:["Amazon","PayPal","Uber"],answer:"1xx info, 2xx success (200 OK, 201 Created, 204 No Content), 3xx redirect (301, 302, 304), 4xx client error (400, 401, 403, 404, 429), 5xx server error (500, 502, 503, 504).",tips:"Know the top 10 codes cold."},
  {q:"What is idempotency in HTTP methods?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","PayPal","Stripe"],answer:"An operation is idempotent if repeated calls have the SAME effect as one call. GET, PUT, DELETE are idempotent. POST is NOT. Idempotency lets clients safely retry on failures.",tips:"Idempotency is critical for reliable retries."},
  {q:"What are HTTP cookies?",level:"Networking",difficulty:"Advanced",experience:"1-6 Years",company:["Google","Amazon","PayPal"],answer:"Small data pieces stored by browser and sent back with each request to the same origin. Used for sessions, tracking, preferences. Flags: HttpOnly (no JS access), Secure (HTTPS only), SameSite (CSRF protection).",tips:"HttpOnly + Secure + SameSite=Lax is the safe default."},
  {q:"What is a CDN cache miss vs cache hit?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Cloudflare","Netflix","Amazon"],answer:"Hit: CDN edge has the resource, serves directly (fast, cheap). Miss: edge fetches from origin (slower, more expensive). Metrics: cache hit ratio. Tune TTLs and vary headers to maximize hits.",tips:"Aim for 90%+ cache hit ratio for static content."},
  {q:"What is DNS TTL and why does it matter?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Cloudflare","Amazon","Google"],answer:"Time-To-Live — how long resolvers cache a DNS record. Long TTL = fewer queries + slow propagation on change. Short TTL = fast changes + more queries. Typically 300-3600s. Lower before planned changes.",tips:"Lower TTL 24h before a DNS migration."},
  {q:"What is a WAF?",level:"Networking",difficulty:"Advanced",experience:"2-7 Years",company:["Cloudflare","Amazon","Google"],answer:"Web Application Firewall — inspects HTTP requests and blocks malicious ones (SQLi, XSS, bots) before they hit your app. Cloud-managed (Cloudflare, AWS WAF) or self-hosted (ModSecurity).",tips:"Layered defense: CDN + WAF + app-level validation."},
  {q:"What is TLS session resumption?",level:"Networking",difficulty:"Expert",experience:"3-8 Years",company:["Google","Cloudflare"],answer:"Reuses cryptographic parameters from a previous TLS handshake to skip full handshake. Session IDs (server-side) or Session Tickets (client-side, stateless). TLS 1.3 also has 0-RTT for repeat connections. Big latency win.",tips:"TLS 1.3 0-RTT is a major perf improvement."},
  {q:"What is BGP?",level:"Networking",difficulty:"Expert",experience:"4-10+ Years",company:["Cisco","Cloudflare","Google"],answer:"Border Gateway Protocol — internet's routing protocol between autonomous systems (ISPs). Path-vector algorithm advertising routes. Misconfigurations can cause global outages (Facebook 2021, Cloudflare 2020s incidents).",tips:"BGP hijacks and misconfigs cause famous internet outages."},
  {q:"What is Anycast?",level:"Networking",difficulty:"Expert",experience:"3-8 Years",company:["Cloudflare","Google","AWS"],answer:"Same IP advertised from multiple locations via BGP. Traffic routes to the NEAREST (network-wise) location automatically. Used by CDNs, DNS (8.8.8.8), and DDoS absorption.",tips:"Anycast is why 1.1.1.1 feels fast everywhere."}
);


/* ==================== BATCH: LLM & AI SPECIALTY ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"What is LangChain?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Startups","Meta"],answer:"An orchestration framework for building LLM apps: chains prompts + retrievers + tools + memory. Provides abstractions for RAG, agents, and multi-step workflows. Alternatives: LlamaIndex, LangGraph, DSPy.",tips:"LangChain is the biggest LLM framework; LlamaIndex focuses on RAG."},
  {q:"What is a LangChain agent?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Anthropic","Startups"],answer:"An LLM that decides which TOOLS to call and in what order to complete a task. Uses a ReAct loop (Reason + Act). Tools can be API calls, DB queries, code execution. Risky without guardrails.",tips:"ReAct loop = Thought -> Action -> Observation -> repeat."},
  {q:"What is function/tool calling in LLMs?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-7 Years",company:["OpenAI","Anthropic","Google"],answer:"Model outputs structured JSON matching a function schema instead of free text. Your code executes the function and feeds results back. Enables reliable agents and API integrations. OpenAI, Anthropic, Gemini all support it.",tips:"Function calling >> parsing free-text output. Always prefer it."},
  {q:"What is RAG in detail?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Meta","Startups"],answer:"Retrieval-Augmented Generation: 1) chunk documents. 2) embed each chunk. 3) store in vector DB. 4) on query, embed + retrieve top-K similar chunks. 5) inject into LLM prompt as context. Grounds responses in your data.",tips:"Chunk size, overlap, and re-ranking are key tuning knobs."},
  {q:"What are chunking strategies for RAG?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-7 Years",company:["OpenAI","Startups"],answer:"Fixed-size (simplest, worst results), sentence/paragraph-aware, semantic chunking (embed then split at semantic breaks), recursive (split on ##, then ##, then \\n\\n), hierarchical. Overlap 10-20% preserves context across chunks.",tips:"Semantic + hierarchical chunking beat fixed-size for quality."},
  {q:"What is a vector similarity metric?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"2-7 Years",company:["OpenAI","Meta","Startups"],answer:"Cosine similarity (most common, angle-based, ignores magnitude). Dot product (fast, needs normalized vectors). Euclidean/L2 (magnitude matters). Match to the embedding model's training objective.",tips:"Most embedding models are trained for cosine similarity."},
  {q:"What is HNSW?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["OpenAI","Startups"],answer:"Hierarchical Navigable Small World — approximate nearest neighbor graph algorithm. Multi-layer skip-list-like structure enables fast (log n) search with high recall. Used by most vector DBs (Pinecone, Weaviate, Qdrant).",tips:"HNSW is the dominant ANN algorithm; IVF-Flat is another common one."},
  {q:"What is hybrid search?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["OpenAI","Startups"],answer:"Combines semantic vector search + keyword search (BM25/TF-IDF), then merges/re-ranks results. Semantic finds meaning; keyword catches exact matches (product IDs, names). Beats pure vector search on most benchmarks.",tips:"Hybrid + reranker = state-of-the-art retrieval."},
  {q:"What is a re-ranker?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["OpenAI","Meta","Startups"],answer:"A second-stage model (cross-encoder) that scores query-passage pairs after initial retrieval. Retriever returns top-100 fast; reranker picks top-10 accurately. Slower but much better relevance. E.g., Cohere Rerank, BGE-reranker.",tips:"Retriever fast + Reranker accurate = production pattern."},
  {q:"What is prompt engineering?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Anthropic","Google"],answer:"Crafting prompts to get better LLM outputs. Techniques: clear instructions, few-shot examples, chain-of-thought ('think step by step'), role assignment, output format specification, XML tags for structure.",tips:"Few-shot examples often beat long instructions."},
  {q:"What is chain-of-thought prompting?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Google","Anthropic"],answer:"Ask the model to 'think step by step' before answering. Dramatically improves reasoning on math, logic, and multi-step problems. Recent thinking models (o1, o3, Claude thinking) do this internally.",tips:"'Let's think step by step' is a magic phrase for reasoning."},
  {q:"What is temperature in LLMs?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Google","Anthropic"],answer:"Controls sampling randomness. 0 = deterministic, always most-likely token. 0.7-1.0 = creative. >1.0 = chaotic. Use 0 for extraction/classification, higher for creative writing.",tips:"Extraction/classification: temp=0. Creative: temp=0.7-1.0."},
  {q:"What is top-p (nucleus sampling)?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-7 Years",company:["OpenAI","Anthropic"],answer:"Sample from the smallest set of tokens whose cumulative probability exceeds p (e.g., 0.9). Adapts to token distribution — narrow when the model is confident, wide when it's not. Alternative to temperature.",tips:"top-p adapts to confidence; often used instead of temperature."},
  {q:"What is the context window?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Anthropic","Google"],answer:"Max input tokens a model can process at once. GPT-4 Turbo: 128k. Claude 3.5 Sonnet: 200k. Gemini 1.5 Pro: 1M+. Longer = more capable but slower and more expensive per call.",tips:"Long context isn't free — attention is quadratic in cost."},
  {q:"What is fine-tuning vs LoRA?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Meta","Anthropic"],answer:"Full fine-tuning updates ALL parameters (expensive). LoRA (Low-Rank Adaptation) freezes the base model and trains SMALL rank-decomposed matrices — 10-100x less memory and compute with comparable quality.",tips:"LoRA/QLoRA is the practical way to fine-tune large models."},
  {q:"What is RLHF?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["OpenAI","Anthropic","Meta"],answer:"Reinforcement Learning from Human Feedback: train a reward model on human preference comparisons, then RL-optimize the LLM against it. Turned base GPT-3 into ChatGPT. DPO is a simpler modern alternative.",tips:"RLHF = 'align' base model with human preferences."},
  {q:"What is DPO?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["Meta","Anthropic"],answer:"Direct Preference Optimization — trains directly on preference pairs (chosen vs rejected) with a closed-form loss. No separate reward model or RL. Simpler and often as good as RLHF.",tips:"DPO is the modern lighter-weight RLHF alternative."},
  {q:"What is hallucination?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-7 Years",company:["OpenAI","Anthropic","Meta"],answer:"LLM outputs that are plausible but factually wrong or unsupported. Mitigations: RAG with grounded sources, structured outputs, verification against tools, lower temperature, citations, and evals.",tips:"Grounding (RAG) + citations is the main defense."},
  {q:"What is model distillation?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta","OpenAI"],answer:"Train a small 'student' model to mimic a large 'teacher' model's outputs. Preserves most quality at a fraction of the cost. Used to create fast open-weight models from large frontier models.",tips:"Distillation gives 90% quality at 10% cost."},
  {q:"What is quantization?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["Meta","NVIDIA","Google"],answer:"Represent weights with fewer bits (fp16 -> int8 -> int4). Dramatically shrinks model size and speeds inference with modest quality loss. Enables running large models on consumer hardware.",tips:"Int4 quant runs 70B models on a single high-end GPU."},
  {q:"What is a system prompt?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Anthropic","Google"],answer:"Special initial message that sets the model's persona, role, rules, and constraints. Sent before user messages. Ideal for stable instructions. Not perfectly resistant to prompt injection.",tips:"System prompts steer behavior but don't guarantee it."},
  {q:"What is prompt caching?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-7 Years",company:["OpenAI","Anthropic","Google"],answer:"Reuses computed key-value states for repeated prompt prefixes. Anthropic and OpenAI offer it — cache large system prompts / RAG contexts to slash cost and latency on repeat calls.",tips:"Cache long stable prefixes (system, context) for 90% savings."},
  {q:"What is a token in an LLM?",level:"LLM & AI Specialty",difficulty:"Beginner",experience:"0-5 Years",company:["OpenAI","Google","Anthropic"],answer:"A subword unit produced by the tokenizer. ~4 chars in English. Cost and context limits are measured in tokens. Different models use different tokenizers (BPE, SentencePiece).",tips:"1 English word ≈ 1.3 tokens."},
  {q:"What is an embedding model?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Meta","Google"],answer:"A model that maps text/images/audio to dense vectors where similar meanings are close. Examples: text-embedding-3-large (OpenAI), bge-m3, cohere-embed. Foundation of RAG and semantic search.",tips:"Match embedding model to your language and domain."},
  {q:"What are LLM evals?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Anthropic","Startups"],answer:"Automated tests for LLM apps. Types: exact match, LLM-as-judge (another LLM grades), regex/schema checks, human eval. Frameworks: Ragas, DeepEval, LangSmith. Ship-safe LLM code requires evals.",tips:"'LLM-as-judge' is standard for open-ended eval."},
  {q:"What is guardrails / output validation?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Anthropic","Startups"],answer:"Validate LLM output before use: JSON schema, regex, allowed values, PII scrubbing, toxicity checks. Retry with error feedback if invalid. Libraries: Guardrails AI, Instructor, Pydantic AI.",tips:"Instructor + Pydantic is the popular Python combo."},
  {q:"What is a multi-agent system?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"2-8 Years",company:["OpenAI","Anthropic","Startups"],answer:"Multiple specialized LLM agents that collaborate (planner, coder, reviewer). Frameworks: LangGraph, CrewAI, AutoGen. Can be more capable than a single agent but harder to control and debug.",tips:"Start with a single agent; add more only if truly needed."},
  {q:"What is MCP (Model Context Protocol)?",level:"LLM & AI Specialty",difficulty:"Expert",experience:"1-7 Years",company:["Anthropic","OpenAI","Startups"],answer:"Open standard by Anthropic for connecting LLMs to tools, data sources, and prompts. Servers expose capabilities; clients (chat apps) discover and use them. Solves the M*N integration problem.",tips:"MCP is emerging as the 'USB-C for AI tools'."},
  {q:"What is a rate limit for LLM APIs?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Anthropic"],answer:"Providers cap requests/tokens per minute (RPM/TPM). Exceed = 429. Handle with exponential backoff + jitter, request queueing, or dedicated capacity (Azure OpenAI PTUs).",tips:"Backoff + retry + queue is the standard pattern."},
  {q:"What is streaming in LLM responses?",level:"LLM & AI Specialty",difficulty:"Advanced",experience:"1-6 Years",company:["OpenAI","Anthropic","Google"],answer:"Server sends tokens as generated via SSE/WebSocket, so users see text appearing word-by-word. Reduces perceived latency dramatically. Client accumulates deltas.",tips:"Streaming makes UX feel 5x faster."}
);


/* ==================== BATCH: CLOUD ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"What is the difference between IaaS, PaaS, and SaaS?",level:"Cloud",difficulty:"Beginner",experience:"0-5 Years",company:["Amazon","Microsoft","Google"],answer:"IaaS: raw infra (EC2, VMs) — you manage OS+app. PaaS: platform (Heroku, App Engine) — you manage code only. SaaS: full app (Gmail, Salesforce) — you just use it.",tips:"IaaS=infra, PaaS=platform, SaaS=software."},
  {q:"What is AWS Lambda?",level:"Cloud",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Netflix","Startups"],answer:"Serverless compute — you upload a function, AWS runs it on demand. Scales automatically, pay per invocation + duration. Cold start latency is the main tradeoff. Alternatives: Google Cloud Functions, Azure Functions.",tips:"Cold starts hurt; use provisioned concurrency for latency-sensitive apps."},
  {q:"What is AWS S3 used for?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Netflix","Startups"],answer:"Object storage: files, images, backups, static websites, data lakes. 11 9s durability, tiered pricing (Standard, IA, Glacier). Not a filesystem — no random writes. Versioning and lifecycle policies built-in.",tips:"S3 = object store, not a filesystem."},
  {q:"What is AWS DynamoDB?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"Managed NoSQL key-value/document DB. Single-digit ms latency, scales to millions of RPS, pay-per-request or provisioned. Uses partition key + optional sort key. Great for high-scale simple access patterns.",tips:"Design your access patterns FIRST; DynamoDB isn't SQL."},
  {q:"What is AWS RDS?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Startups"],answer:"Managed relational DB (MySQL, Postgres, Oracle, SQL Server, Aurora). AWS handles patching, backups, replication, failover. Aurora is AWS's cloud-native variant — cheaper storage, faster than stock MySQL/Postgres.",tips:"Aurora Serverless v2 scales compute automatically."},
  {q:"What is AWS SQS vs SNS?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"SQS: queue — one message goes to ONE consumer. SNS: pub/sub topic — one message fanned out to MANY subscribers (email, SQS, Lambda, HTTP). Common pattern: SNS -> multiple SQS -> consumers.",tips:"SQS=queue, SNS=broadcast. Combine them for durable fanout."},
  {q:"What is AWS EC2 vs Fargate?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"EC2: virtual machines you manage. Fargate: serverless containers — you provide a container image, AWS runs it without managing servers. Fargate simplifies ops; EC2 is cheaper at scale.",tips:"Fargate for simplicity; EC2 for cost control at scale."},
  {q:"What is AWS IAM in depth?",level:"Cloud",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Netflix","PayPal"],answer:"Identity & Access Management. Entities: users, groups, roles. Policies (JSON) attach to entities specifying allowed/denied actions on resources. Roles for services (never hardcode keys). Principle: least privilege.",tips:"Use IAM roles for EC2/Lambda, never access keys."},
  {q:"What is AWS VPC?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix","PayPal"],answer:"Virtual Private Cloud — isolated network in AWS. Subnets (public/private per AZ), route tables, security groups (instance firewall), NACLs (subnet firewall), internet gateway, NAT gateway. Isolates workloads.",tips:"Public subnet = has route to Internet Gateway; private = uses NAT."},
  {q:"What is AWS CloudFront?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Netflix"],answer:"AWS's CDN — caches content at 400+ edge locations. Integrates with S3, ALB, Lambda@Edge. Provides TLS termination, WAF, DDoS protection (Shield).",tips:"CloudFront + S3 = classic static site delivery."},
  {q:"What is AWS CloudWatch?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Netflix"],answer:"Metrics, logs, alarms, dashboards, events. Every AWS service integrates. CloudWatch Logs Insights for log queries; CloudWatch Metrics for numeric time-series; Alarms trigger actions (SNS, Lambda).",tips:"CloudWatch is AWS's observability Swiss army knife."},
  {q:"What is Kinesis vs Kafka?",level:"Cloud",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Netflix","Uber"],answer:"Kinesis: AWS-managed stream, similar model to Kafka but simpler and integrated. Kafka: OSS, richer features, portable across clouds. Kinesis is easier ops; Kafka has bigger ecosystem.",tips:"Kinesis if all-in on AWS; Kafka for portability + power."},
  {q:"What is AWS EventBridge?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"Serverless event bus. Route events between AWS services, SaaS apps, and custom apps via rules. Replaces SNS + Lambda glue for event-driven architectures. Schema registry included.",tips:"EventBridge = SNS on steroids for event-driven apps."},
  {q:"What is Kubernetes on AWS (EKS)?",level:"Cloud",difficulty:"Advanced",experience:"2-8 Years",company:["Amazon","Netflix"],answer:"AWS-managed Kubernetes control plane. You manage worker nodes (or use Fargate profiles). Integrates with IAM, ALB, EBS, CloudWatch. Standard Kubernetes API — portable.",tips:"EKS+Fargate = 'K8s without managing nodes'."},
  {q:"What is Azure vs AWS vs GCP at a high level?",level:"Cloud",difficulty:"Intermediate",experience:"1-8 Years",company:["Microsoft","Amazon","Google"],answer:"AWS: largest, most services, dominant. Azure: strong for enterprise/MSFT shops, best hybrid story. GCP: strong data/AI/K8s (Google invented K8s), fewer services. All 3 are 'good enough' — pick based on team skills and enterprise contracts.",tips:"Multi-cloud is rare and expensive — pick one and go deep."},
  {q:"What is Azure Functions?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Microsoft"],answer:"Azure's serverless functions equivalent to AWS Lambda. Triggers: HTTP, timer, blob, queue. Durable Functions extend it for long-running stateful workflows. Python, C#, Node, Java supported.",tips:"Durable Functions add stateful orchestration to serverless."},
  {q:"What is GCP BigQuery?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Google","Startups"],answer:"Serverless columnar data warehouse. Scales to petabytes, pay per query (bytes scanned) or reserved slots. SQL interface, ML built-in (BigQuery ML). Snowflake competitor.",tips:"BigQuery = fully-managed columnar analytics, pay per byte."},
  {q:"What is serverless in the cloud?",level:"Cloud",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Google","Azure"],answer:"'No servers to manage' — cloud runs your code/data on shared infra, scales automatically, bills per use. Examples: Lambda, DynamoDB, S3, BigQuery, Cloud Run. Downsides: cold starts, less control, potential vendor lock-in.",tips:"Serverless != no servers; it's YOU don't manage them."},
  {q:"What is a cloud region vs availability zone?",level:"Cloud",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Google","Microsoft"],answer:"Region: geographic area (us-east-1). Availability Zone (AZ): isolated data center(s) within a region. Deploy across multiple AZs for HA within a region; multiple regions for disaster recovery.",tips:"Multi-AZ for HA; multi-region for DR."},
  {q:"What is Multi-AZ deployment?",level:"Cloud",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Netflix"],answer:"Deploy identical infrastructure across 2+ AZs behind a load balancer or with DB failover. If one AZ fails, traffic shifts. Standard for HA production systems. Cost: 2-3x for compute.",tips:"Multi-AZ is table-stakes for production; multi-region for critical apps."},
  {q:"What is Terraform vs CloudFormation?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"Terraform: multi-cloud (HashiCorp), HCL syntax, huge community, plan-then-apply. CloudFormation: AWS-native, JSON/YAML, deep AWS integration, drift detection. Terraform wins for multi-cloud; CloudFormation for AWS-only shops.",tips:"Terraform is the industry standard; CloudFormation for AWS-only."},
  {q:"What is a cloud NAT gateway?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google"],answer:"Managed service allowing instances in a PRIVATE subnet to reach the internet (outbound only) — for updates, calling external APIs. Instances stay unreachable from outside. Charged per hour + data.",tips:"NAT = private subnet outbound internet; not inbound."},
  {q:"What is a security group vs NACL?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon"],answer:"Security Group: STATEFUL firewall on EC2/ENI (return traffic auto-allowed). NACL: STATELESS firewall on subnet (need explicit allow both ways). SGs are more common; NACLs for extra defense-in-depth.",tips:"SG=stateful+instance, NACL=stateless+subnet."},
  {q:"What is auto-scaling group?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"AWS group of EC2 instances scaled automatically based on metrics (CPU, request count) or schedule. Set min/max/desired. Uses launch templates. Integrates with ELB for zero-downtime scaling.",tips:"ASG + ALB + CloudWatch alarms = classic elastic app."},
  {q:"What is cloud cost optimization?",level:"Cloud",difficulty:"Advanced",experience:"2-8 Years",company:["Amazon","Netflix","Startups"],answer:"Right-size instances, use Spot/preemptible VMs for batch, Reserved/Savings Plans for steady load, delete unused resources, S3 lifecycle policies (Glacier), stop dev in off-hours, monitor with Cost Explorer + budgets.",tips:"Biggest wins: right-sizing + Spot instances + storage tiering."},
  {q:"What are spot instances?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix"],answer:"Unused EC2 capacity at up to 90% discount, but can be reclaimed with 2-min notice. Great for stateless/batch/fault-tolerant workloads (ML training, CI, data processing). Not for stateful services.",tips:"Spot = 90% discount but ephemeral; use for stateless batch."},
  {q:"What is a bastion host?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","PayPal"],answer:"A hardened jump server in a public subnet that admins SSH into to then reach private-subnet servers. Modern alternative: AWS Systems Manager Session Manager (no bastion, no SSH keys needed).",tips:"SSM Session Manager > bastion in modern AWS setups."},
  {q:"What is AWS Cognito?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Startups"],answer:"Managed user auth service. User Pools (sign-up/sign-in, MFA, social login, JWT tokens). Identity Pools (federated identities for temp AWS credentials). Alternative: Auth0, Firebase Auth.",tips:"Cognito for AWS-native; Auth0 for polish and DX."},
  {q:"What is Cloud Run (GCP)?",level:"Cloud",difficulty:"Advanced",experience:"2-7 Years",company:["Google"],answer:"Fully-managed container platform. Deploy a container image; Cloud Run scales it 0-N based on requests. Faster cold starts than Lambda for containers. Great sweet spot between Lambda and Kubernetes.",tips:"Cloud Run = serverless containers with fast cold starts."},
  {q:"What is Infrastructure Drift?",level:"Cloud",difficulty:"Expert",experience:"3-8 Years",company:["Netflix","Amazon","Google"],answer:"When actual cloud state diverges from IaC declared state (manual changes in console, other tools). Terraform 'refresh' or CloudFormation 'drift detection' identifies it. Fix by re-applying IaC or updating code.",tips:"Prevent by disabling manual console changes in production."}
);


/* ==================== BATCH: FRONTEND & FULL-STACK ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"What is the difference between == and === in JavaScript?",level:"Frontend & Full-Stack",difficulty:"Beginner",experience:"0-4 Years",company:["Meta","Google","Startups"],answer:"== does type coercion ('5' == 5 is true). === strict equality, no coercion ('5' === 5 is false). ALWAYS use === in modern JavaScript.",tips:"Use === always; == has surprising edge cases."},
  {q:"What is React?",level:"Frontend & Full-Stack",difficulty:"Beginner",experience:"0-5 Years",company:["Meta","Startups"],answer:"A JavaScript library for building component-based UIs. Uses a virtual DOM and unidirectional data flow. Written by Meta, open-source. Modern React uses functional components + hooks.",tips:"Functional components + hooks is the modern React style."},
  {q:"What are React hooks?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Netflix","Startups"],answer:"Functions that let functional components use state and lifecycle features. Core hooks: useState, useEffect, useContext, useReducer, useMemo, useCallback, useRef. Custom hooks share reusable stateful logic.",tips:"Rules: only call hooks at top level, only from React functions."},
  {q:"What is the virtual DOM?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Netflix"],answer:"An in-memory representation of the real DOM. React diffs new vs old virtual DOM to compute the minimum set of real DOM updates. Faster than direct DOM manipulation for complex UIs.",tips:"Not always faster — signals-based frameworks (Solid, Svelte) skip vDOM entirely."},
  {q:"What is the difference between props and state in React?",level:"Frontend & Full-Stack",difficulty:"Beginner",experience:"0-4 Years",company:["Meta","Startups"],answer:"Props: read-only inputs passed from parent to child. State: internal, mutable data owned by the component. Change props by re-rendering parent; change state with useState/setState.",tips:"Props flow down; state is local."},
  {q:"What is useEffect and when does it run?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Netflix"],answer:"Runs side effects after render. useEffect(fn, [deps]) — runs after every render if deps change; [] means once on mount. Cleanup function runs before next effect or unmount.",tips:"Empty deps [] = 'run once on mount' pattern."},
  {q:"What is TypeScript?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-7 Years",company:["Meta","Microsoft","Startups"],answer:"A typed superset of JavaScript that compiles to JS. Adds static types, interfaces, generics, enums. Catches errors at compile time. Now standard for large JS codebases.",tips:"TS is basically mandatory for large frontend/backend JS teams."},
  {q:"What is the difference between interface and type in TypeScript?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Microsoft","Meta"],answer:"Interface: object shapes, declaration merging (can be extended). Type: more flexible (unions, intersections, mapped types, primitives). Use interface for objects; type for complex compositions.",tips:"Objects=interface, unions/complex=type — rough rule."},
  {q:"What is a REST API vs GraphQL?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"2-7 Years",company:["Meta","GitHub","Shopify","Netflix"],answer:"REST: multiple endpoints, fixed responses, HTTP verbs, over-fetching common. GraphQL: single endpoint, client specifies exactly what fields to fetch, avoids over/under-fetching, strong schema, subscriptions for real-time.",tips:"GraphQL for complex UIs with varied data needs; REST for simple public APIs."},
  {q:"What are GraphQL queries, mutations, and subscriptions?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"2-7 Years",company:["Meta","GitHub","Shopify"],answer:"Query: read data (like GET). Mutation: modify data (like POST/PUT/DELETE). Subscription: real-time push updates (over WebSocket). All defined in the schema.",tips:"Query/Mutation/Subscription = read/write/stream."},
  {q:"What is the difference between SSR, SSG, and CSR?",level:"Frontend & Full-Stack",difficulty:"Expert",experience:"2-7 Years",company:["Meta","Vercel","Netflix"],answer:"CSR (Client-Side): browser renders empty HTML then runs JS to build UI. SSR (Server-Side): server renders HTML per request. SSG (Static Site Gen): pre-renders at build time. Modern: Next.js supports all three.",tips:"SSG for content sites, SSR for personalized pages, CSR for apps."},
  {q:"What is Next.js?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Vercel","Meta","Netflix"],answer:"Full-stack React framework by Vercel. Provides file-based routing, SSR/SSG/ISR, API routes, image optimization, and the App Router (React Server Components). Standard choice for production React apps.",tips:"Next.js App Router + RSC is the current React frontier."},
  {q:"What are React Server Components?",level:"Frontend & Full-Stack",difficulty:"Expert",experience:"2-7 Years",company:["Meta","Vercel","Netflix"],answer:"Components rendered on the server, streaming HTML+data to the client without shipping their JS. Enables DB queries and secrets inside components. Client components handle interactivity. Reduces bundle size.",tips:"RSC = server components + client components hybrid model."},
  {q:"What is CSS-in-JS?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Startups"],answer:"Writing CSS in JavaScript files (styled-components, emotion). Enables dynamic styles based on props, scoping, and TypeScript integration. Trade-off: runtime cost. Alternatives: CSS Modules, Tailwind (utility-first).",tips:"Tailwind is winning against CSS-in-JS for perf reasons."},
  {q:"What is Tailwind CSS?",level:"Frontend & Full-Stack",difficulty:"Intermediate",experience:"1-5 Years",company:["Vercel","Startups"],answer:"Utility-first CSS framework — you compose classes like `bg-blue-500 p-4` directly in JSX. No custom CSS files needed. JIT compiles only used classes. Fast, consistent, but classes can get long.",tips:"Tailwind is the modern default; @apply for reusability."},
  {q:"What is a Progressive Web App (PWA)?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"2-7 Years",company:["Google","Microsoft"],answer:"Web app that behaves like a native app: installable, offline-capable (service workers), push notifications, background sync. Manifest.json + service worker are the core.",tips:"PWA = web + native-like features without app stores."},
  {q:"What is a service worker?",level:"Frontend & Full-Stack",difficulty:"Expert",experience:"3-8 Years",company:["Google","Microsoft"],answer:"Background JS script that intercepts network requests and can serve cached responses — enables offline mode, background sync, push notifications. Runs separately from the main page.",tips:"Service workers = offline + background capabilities for web apps."},
  {q:"What is the DOM?",level:"Frontend & Full-Stack",difficulty:"Beginner",experience:"0-4 Years",company:["Meta","Google","Startups"],answer:"Document Object Model — tree representation of an HTML document that JS can manipulate. Every element is a node. Modifying the DOM re-renders the page.",tips:"DOM = tree of nodes representing HTML/XML."},
  {q:"What is event bubbling and capturing?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Google"],answer:"Bubbling: event fires on target, then bubbles UP to ancestors. Capturing: event goes DOWN from root to target first, then bubbles. addEventListener's third arg (or {capture: true}) sets the mode.",tips:"Bubbling is default; capture is opt-in."},
  {q:"What is event delegation?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Google"],answer:"Attach ONE listener on a parent element that handles events for all children via event.target. Handles dynamically added children too. Faster than N individual listeners.",tips:"One listener > N listeners for lists."},
  {q:"What is a closure in JavaScript?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Google"],answer:"Function that captures variables from its enclosing scope, remembered even after the outer function returns. Same concept as Python closures. Used in module patterns, currying, callbacks.",tips:"Same idea as Python closures — captured variables live on."},
  {q:"What is 'this' in JavaScript?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Google","Microsoft"],answer:"Refers to the CALLING context (dynamic). In methods: the object. In regular functions: undefined (strict) or globalThis. Arrow functions LEXICALLY bind 'this' from enclosing scope.",tips:"Arrow functions lock 'this' — very useful in class methods and callbacks."},
  {q:"What is Redux vs React Context?",level:"Frontend & Full-Stack",difficulty:"Expert",experience:"2-7 Years",company:["Meta","Netflix"],answer:"Redux: predictable global store, single source of truth, time-travel debugging, middleware. Context: React-native, passes values without prop drilling, no store patterns. For complex state prefer Redux Toolkit or Zustand.",tips:"Modern: Zustand or Redux Toolkit; Context for simple cases."},
  {q:"What is React Query / TanStack Query?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"2-7 Years",company:["Meta","Vercel","Netflix"],answer:"A data-fetching library that handles caching, refetching, mutations, and state. Removes the need to manage server state in Redux. Standard for React apps that call APIs.",tips:"For server state, use React Query — don't put it in Redux."},
  {q:"What is Node.js?",level:"Frontend & Full-Stack",difficulty:"Beginner",experience:"0-5 Years",company:["Meta","Netflix","Startups"],answer:"JavaScript runtime built on Chrome's V8 engine. Enables server-side JS. Event-driven, non-blocking I/O — great for I/O-heavy apps. NPM is the largest package ecosystem.",tips:"Node event loop + libuv = single-threaded async I/O."},
  {q:"What is React reconciliation?",level:"Frontend & Full-Stack",difficulty:"Expert",experience:"2-7 Years",company:["Meta","Netflix"],answer:"React's diffing algorithm between virtual DOMs. Uses element type + key to match nodes. Same type + same key: reuse. Different: unmount old + mount new. Fiber architecture makes it interruptible.",tips:"Always give a stable unique 'key' when rendering lists."},
  {q:"What is a memoized component?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-6 Years",company:["Meta","Netflix"],answer:"React.memo wraps a functional component to skip re-render if props are shallowly equal. useMemo caches an expensive computation. useCallback caches a function reference. Use sparingly — profile first.",tips:"Premature memoization is worse than no memoization."},
  {q:"What is a JWT vs session cookie for auth?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"2-7 Years",company:["Google","Meta","PayPal"],answer:"JWT: stateless, signed token in Authorization header, works across services, hard to revoke. Session cookie: server tracks state, easy to revoke, tied to a session store. Cookies safer for web apps; JWT common for APIs/mobile.",tips:"For web: HttpOnly session cookies. For APIs/mobile: JWT."},
  {q:"What is CSS specificity?",level:"Frontend & Full-Stack",difficulty:"Advanced",experience:"1-5 Years",company:["Google","Meta"],answer:"Weight of a CSS selector determining which rule applies. Order: inline > ID > class/attr/pseudo-class > element/pseudo-element. !important overrides all. Higher specificity wins ties.",tips:"Avoid !important; use lower specificity + source order."},
  {q:"What is a mobile-first design?",level:"Frontend & Full-Stack",difficulty:"Intermediate",experience:"1-6 Years",company:["Google","Meta"],answer:"Design and code for mobile FIRST, then progressively enhance for larger screens. Uses min-width media queries. Ensures fast, functional mobile UX — where most users are.",tips:"min-width media queries are the mobile-first pattern."}
);


/* ==================== BATCH: DATABASE DEEP-DIVE ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"What is a B-tree index?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal","Google"],answer:"A balanced multi-way tree used for most database indexes. Keeps data sorted; O(log n) lookups, ranges, inserts, deletes. Postgres, MySQL, Oracle default to B-trees. Trade-off: slower writes vs faster reads.",tips:"B-tree = default; hash indexes for equality-only."},
  {q:"When should you NOT create an index?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal"],answer:"On small tables, on columns with low cardinality (e.g., boolean), on frequently-updated columns (index maintenance cost), and on tables optimized for write throughput. Every index slows writes.",tips:"Indexes are not free — measure before adding."},
  {q:"What is a composite index?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal","Google"],answer:"Index on multiple columns (col_a, col_b). Order matters — usable for queries filtering on col_a alone, or col_a AND col_b, but NOT col_b alone. Match the leftmost prefix rule.",tips:"Column order = query pattern order."},
  {q:"What is a covering index?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","Google"],answer:"An index that includes all columns the query needs, so the DB reads only the index — no heap/table lookup. Massive speedup. Use INCLUDE clause in Postgres/SQL Server to add non-key columns.",tips:"Covering index avoids the 'lookup table' step — big win."},
  {q:"What is a query execution plan?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-8 Years",company:["Amazon","Oracle","PayPal"],answer:"The step-by-step plan the DB will run: which indexes, join order, sort/hash. EXPLAIN (Postgres/MySQL) shows it; EXPLAIN ANALYZE runs and measures. Debug slow queries by reading this plan.",tips:"EXPLAIN ANALYZE is your #1 tool for slow queries."},
  {q:"What is a full table scan?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Oracle"],answer:"DB reads EVERY row — happens when no useful index exists or query would return >~10-20% of rows. On huge tables, disastrous. Fix: add proper index, rewrite query, or partition the table.",tips:"See 'Seq Scan' on large tables = investigate."},
  {q:"What is a hash join vs nested loop vs merge join?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","Google"],answer:"Nested loop: O(N*M) — fast for small inner/outer with index. Hash join: build hash table on one side, probe with other — great for large unsorted sets. Merge join: sort both sides then merge — good for already-sorted data.",tips:"Optimizer picks based on stats; hash is common for big joins."},
  {q:"What are ACID properties?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Oracle","PayPal"],answer:"Atomicity: all-or-nothing. Consistency: valid state to valid state. Isolation: concurrent transactions don't see each other's partial state. Durability: committed data survives crashes.",tips:"ACID is the transactional guarantee — mostly SQL, some NoSQL."},
  {q:"What are the SQL isolation levels?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal"],answer:"Read Uncommitted (dirty reads allowed), Read Committed (default in Postgres/Oracle), Repeatable Read (default in MySQL/InnoDB), Serializable (strictest, may cause conflicts). Higher = less concurrency, more consistency.",tips:"Default: Read Committed (Postgres/Oracle) or RR (MySQL)."},
  {q:"What is optimistic vs pessimistic locking?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal"],answer:"Optimistic: no lock; check version column on update, retry if changed. Great for low-contention. Pessimistic: acquire row lock upfront (SELECT ... FOR UPDATE). Great for high-contention or long transactions.",tips:"Optimistic for read-heavy; pessimistic for hot rows."},
  {q:"What is a deadlock in a database?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","PayPal"],answer:"Two transactions each hold a lock the other needs, waiting forever. DB detects and kills one (deadlock victim). Prevent by acquiring locks in consistent order, keeping transactions short, and using appropriate isolation.",tips:"Always acquire locks in a globally consistent order."},
  {q:"What is a materialized view?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Oracle","Snowflake"],answer:"A cached table storing the result of a query. Refreshed on schedule or event. Speeds up expensive analytics/reporting. Trade-off: stale data vs speed.",tips:"Materialized views trade freshness for read speed."},
  {q:"What is database replication?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-8 Years",company:["Amazon","Oracle","Netflix"],answer:"Copy data from a primary DB to one or more replicas. Sync (safer, slower) or async (faster, possible data loss on failover). Enables read scaling, HA, and DR.",tips:"Sync for zero data loss; async for read scale."},
  {q:"What is master-slave vs master-master replication?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle"],answer:"Master-slave (primary-replica): ONE writer, many read replicas — simple, most common. Master-master: multiple writers — complex conflict resolution, rarely worth it. Prefer primary-replica + failover.",tips:"Multi-master is scary — avoid unless you must."},
  {q:"What is sharding?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Horizontal partitioning: split data across multiple DBs by a shard key (user_id, region). Each shard is independent. Scales writes past a single machine. Cross-shard queries are painful — pick shard key wisely.",tips:"Sharding is the last resort — expensive complexity."},
  {q:"What is a database connection pool?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Oracle","PayPal"],answer:"Pool of pre-opened DB connections reused across requests — opening new ones is very expensive. Configure size based on load and DB capacity. Tools: HikariCP, pgbouncer, SQLAlchemy pool.",tips:"For Postgres at scale, put pgbouncer in front."},
  {q:"What is a transaction log (WAL)?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","Netflix"],answer:"Write-Ahead Log: every change first written to a sequential log BEFORE modifying data files. Enables durability (D in ACID) and crash recovery. Also used for replication (log shipping / logical replication) and CDC.",tips:"WAL is the foundation of durability, replication, and CDC."},
  {q:"What is a read replica?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Oracle","Netflix"],answer:"Copy of a primary DB, used for read-only queries — offloads reads, enables horizontal read scaling. Async lag possible. Route writes to primary, reads to replicas.",tips:"Watch for replication lag — reads may be slightly stale."},
  {q:"What is CAP theorem for databases?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Uber"],answer:"During a network partition, distributed DBs must choose Consistency OR Availability. CP: Postgres cluster, MongoDB. AP: DynamoDB, Cassandra. No 'CA' — partitions happen.",tips:"CAP is about network partitions — pick your trade-off."},
  {q:"What is read-after-write consistency?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","DynamoDB","Cassandra"],answer:"A specific guarantee that AFTER a write, subsequent reads BY THE SAME CLIENT return that write's value (even in an eventually consistent system). Achieved by pinning reads to the primary or using session tokens. Weaker than strong consistency but stronger than eventual.",tips:"Session consistency = weaker than strong, stronger than eventual."},
  {q:"What is a foreign key constraint?",level:"Database Deep-Dive",difficulty:"Intermediate",experience:"1-6 Years",company:["Oracle","Amazon","PayPal"],answer:"A column that references the primary key of another table, enforcing referential integrity — can't insert an order for a non-existent customer. ON DELETE options: CASCADE, SET NULL, RESTRICT.",tips:"FK constraints add overhead — some high-scale systems drop them."},
  {q:"What is normalization?",level:"Database Deep-Dive",difficulty:"Intermediate",experience:"1-6 Years",company:["Oracle","TCS","PayPal"],answer:"Organizing tables to reduce redundancy. 1NF: atomic columns. 2NF: no partial dependency on part of composite key. 3NF: no transitive dependency. BCNF: stricter 3NF.",tips:"3NF is the practical target; denormalize for read performance."},
  {q:"What is denormalization?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Netflix","Meta"],answer:"Intentionally duplicating data across tables to avoid JOINs at read time. Trade-off: faster reads + more storage + write complexity. Used in read-heavy systems, NoSQL, and analytics.",tips:"Denormalize when reads dominate and JOINs are the bottleneck."},
  {q:"What is a stored procedure vs a function?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"1-6 Years",company:["Oracle","PayPal","TCS"],answer:"Both are pre-compiled DB code. Function: returns a value, usable in SQL expressions, no side effects (ideally). Stored procedure: executed with CALL, may have side effects, can return multiple result sets.",tips:"Function=deterministic+usable in queries; SP=procedural+side effects."},
  {q:"What is a trigger?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"2-7 Years",company:["Oracle","PayPal"],answer:"DB code that runs automatically on INSERT/UPDATE/DELETE. Uses: audit logs, computed columns, enforcing complex rules. Powerful but hides business logic — most modern teams prefer app-level enforcement.",tips:"Triggers can hide logic and hurt debugging — use sparingly."},
  {q:"What is MongoDB?",level:"Database Deep-Dive",difficulty:"Intermediate",experience:"1-6 Years",company:["Amazon","Startups"],answer:"Document-oriented NoSQL DB storing JSON-like BSON documents. Flexible schema, horizontal sharding, replica sets for HA. Great for content, catalogs, and rapidly-evolving schemas. Uses find/aggregate query language.",tips:"MongoDB for flexible schemas; SQL for relational integrity."},
  {q:"What is Redis?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"1-7 Years",company:["Amazon","Netflix","Uber"],answer:"In-memory key-value store. Blazing fast (sub-ms), rich data structures (strings, lists, sets, hashes, sorted sets, streams). Used for caching, sessions, leaderboards, rate limiting, queues.",tips:"Redis = caching + more (Lua scripts, pub/sub, streams)."},
  {q:"What is a Redis Sorted Set?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Netflix","Amazon","Uber"],answer:"A set where each member has a score; kept sorted by score. Range queries by score/rank in O(log n). Used for leaderboards, priority queues, and rate limiters (sliding window).",tips:"Sorted sets = leaderboards, rate limiters, priority queues."},
  {q:"What is PostgreSQL vs MySQL?",level:"Database Deep-Dive",difficulty:"Advanced",experience:"1-8 Years",company:["Amazon","Oracle","Startups"],answer:"Postgres: more standards-compliant, richer types (JSONB, arrays, ranges), better extensibility, MVCC. MySQL: simpler, more common in web hosting, InnoDB engine with clustered index. Both are solid; Postgres is trending.",tips:"Modern default is Postgres; MySQL still dominates legacy web."},
  {q:"What is MVCC?",level:"Database Deep-Dive",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Oracle","Netflix"],answer:"Multi-Version Concurrency Control: readers see a consistent snapshot; writers don't block readers. Old row versions kept until no transaction needs them (then vacuumed). Used by Postgres, Oracle, MongoDB.",tips:"MVCC = readers don't block writers. Foundation of modern OLTP."}
);


/* ==================== BATCH: FRESH CODING CHALLENGES (final push) ==================== */
window.DP_INTERVIEW.questions.push(
  {q:"Container With Most Water.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Two pointers from both ends; area = min(h[i], h[j]) * (j-i). Move the shorter side inward. O(n).",code:`def area(h):\n    i,j,best=0,len(h)-1,0\n    while i<j:\n        best=max(best, min(h[i],h[j])*(j-i))\n        if h[i]<h[j]: i+=1\n        else: j-=1\n    return best\nprint(area([1,8,6,2,5,4,8,3,7]))`,output:`49`,tips:"Two pointers — move the shorter side (can only improve by finding taller)."},
  {q:"3Sum: find all unique triplets summing to 0.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Sort. Fix i, use two pointers l,r to find pairs summing to -nums[i]. Skip duplicates. O(n^2).",tips:"Sort first + skip dup — the classic optimization."},
  {q:"Longest Substring with At Most K Distinct Chars.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Meta","Uber"],answer:"Sliding window + dict of char counts. Expand right; when distinct > k, shrink left. Track max length. O(n).",tips:"Sliding window + hashmap — template for 'at most K' problems."},
  {q:"Search in a Rotated Sorted Array.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Modified binary search: one half is always sorted. Decide which side contains target based on nums[mid] vs nums[lo]. O(log n).",tips:"Binary search variant — always one sorted half."},
  {q:"Find First and Last Position of Element in Sorted Array.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google"],answer:"Two binary searches: lower bound and upper bound. O(log n) each.",code:`from bisect import bisect_left, bisect_right\ndef range_(a,t):\n    l=bisect_left(a,t); r=bisect_right(a,t)-1\n    return [l,r] if l<=r else [-1,-1]\nprint(range_([5,7,7,8,8,10],8))`,output:`[3, 4]`,tips:"bisect gives clean O(log n) lower/upper bounds."},
  {q:"Product of Array Except Self.",level:"Coding Problems",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Google","Meta"],answer:"Two passes: prefix products left-to-right, then multiply by suffix products right-to-left. O(n) time, O(1) extra space (excluding output).",code:`def prod(nums):\n    n=len(nums); out=[1]*n\n    left=1\n    for i in range(n): out[i]=left; left*=nums[i]\n    right=1\n    for i in range(n-1,-1,-1): out[i]*=right; right*=nums[i]\n    return out\nprint(prod([1,2,3,4]))`,output:`[24, 12, 8, 6]`,tips:"No division allowed — the two-pass trick is elegant."},
  {q:"Set Matrix Zeroes (in-place).",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Use first row/col as markers; scan and mark zeros there, then apply. Handle first row/col specially. O(1) extra space.",tips:"Reuse the input as auxiliary space to reach O(1)."},
  {q:"Spiral Matrix traversal.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta","Zoho"],answer:"Track top, bottom, left, right boundaries. Traverse right, down, left, up; shrink boundaries. Stop when boundaries cross.",tips:"Boundary approach avoids visited tracking."},
  {q:"Rotate Image 90 degrees in place.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Transpose (swap m[i][j] with m[j][i]), then reverse each row. O(n^2) time, O(1) space.",code:`def rotate(m):\n    n=len(m)\n    for i in range(n):\n        for j in range(i+1,n): m[i][j],m[j][i]=m[j][i],m[i][j]\n    for row in m: row.reverse()`,output:`# rotates in place`,tips:"Transpose + reverse each row = 90° rotation."},
  {q:"Longest Consecutive Sequence.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Put nums in set. For each n, if n-1 not in set (start of a sequence), count length by incrementing. O(n).",code:`def lcs(nums):\n    s=set(nums); best=0\n    for n in s:\n        if n-1 not in s:\n            cur=n; L=1\n            while cur+1 in s: cur+=1; L+=1\n            best=max(best,L)\n    return best\nprint(lcs([100,4,200,1,3,2]))`,output:`4`,tips:"Only start counting from sequence starts — O(n) total."},
  {q:"Sort Colors (Dutch National Flag).",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Three pointers: low, mid, high. If nums[mid]==0 swap with low, low++, mid++. If 1: mid++. If 2 swap with high, high--. One pass, in place.",tips:"Dutch flag = classic 3-way partition."},
  {q:"Find Peak Element.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Binary search: at mid, if nums[mid] < nums[mid+1], peak is right; else left (including mid). O(log n).",tips:"Peak exists on the ascending side."},
  {q:"Search a 2D Matrix (sorted rows).",level:"Coding Problems",difficulty:"Advanced",experience:"2-6 Years",company:["Amazon","Google","Meta"],answer:"Start at top-right (or bottom-left). If target < cell go left; if > go down. O(m+n).",tips:"Staircase search — O(m+n) beats binary search here."},
  {q:"Find K Closest Points to Origin.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Meta","Uber"],answer:"Max-heap of size k with distances. Or use heapq.nsmallest(k, points, key=dist). Or Quickselect for O(n) average.",tips:"nsmallest with key is the cleanest Python approach."},
  {q:"Merge k Sorted Lists.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta","Uber"],answer:"Min-heap of (value, list_index, node). Pop smallest, push its .next. O(N log k).",tips:"Heap of heads is the canonical approach."},
  {q:"Reverse a Linked List in Groups of K.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Count k nodes; if fewer, leave. Reverse the group. Recursively/iteratively connect. Handle final partial group per problem.",tips:"Careful pointer bookkeeping — practice this pattern."},
  {q:"Copy List with Random Pointer.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Two passes with a dict mapping original->copy. First pass: create copies. Second pass: wire next/random using the map. O(n).",tips:"Dict {old_node: new_node} is the trick."},
  {q:"Path Sum in Binary Tree (target sum root-to-leaf).",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"DFS: subtract node.val from target; at leaf, check target==0. Recurse left/right.",tips:"Recursive DFS with running target is the standard."},
  {q:"Lowest Common Ancestor of Binary Tree.",level:"Coding Problems",difficulty:"Expert",experience:"3-8 Years",company:["Amazon","Google","Meta"],answer:"Recurse left and right. If both non-null, current node is LCA. Else return the non-null side.",code:`def lca(root,p,q):\n    if not root or root==p or root==q: return root\n    l=lca(root.left,p,q); r=lca(root.right,p,q)\n    return root if l and r else (l or r)`,output:`# returns LCA node`,tips:"Elegant recursive solution — remember the pattern."},
  {q:"Diameter of Binary Tree.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"DFS returning height; at each node, update diameter = max(diameter, leftHeight + rightHeight).",tips:"Diameter passes through a node; check every node."},
  {q:"Symmetric Tree check.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"Recurse with two pointers: check l.val==r.val AND is_mirror(l.left, r.right) AND is_mirror(l.right, r.left).",tips:"Compare mirrored subtrees — recursion pairs them."},
  {q:"Right View of a Binary Tree.",level:"Coding Problems",difficulty:"Advanced",experience:"2-7 Years",company:["Amazon","Google","Meta"],answer:"BFS level order; take the LAST node of each level. Or DFS visiting right first; record first node at each depth.",tips:"BFS + last-of-level is cleanest."},
  {q:"Word Ladder (shortest transformation).",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Amazon","Google","Meta"],answer:"BFS on words. For each word, generate all 1-letter neighbors; if in dict and unvisited, add to queue. Return distance to end word.",tips:"BFS on implicit graph — words are nodes, 1-letter changes are edges."},
  {q:"Clone Graph.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"BFS/DFS with a dict mapping original->copy. Skip already-cloned nodes. Rebuild neighbors from the map.",tips:"Same idea as clone linked list with random pointer."},
  {q:"Alien Dictionary (topological sort).",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Amazon","Google","Meta","Airbnb"],answer:"Build a graph of char-order constraints from adjacent word pairs. Topological sort (Kahn's BFS or DFS). Detect cycles = invalid order.",tips:"Character order = directed graph => topo sort."},
  {q:"Task Scheduler with cooldown.",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Amazon","Meta","Uber"],answer:"Count task frequencies. Result = max((maxFreq-1)*(n+1) + numMaxFreq, totalTasks). Elegant math instead of simulation.",tips:"Math formula beats heap simulation."},
  {q:"LFU Cache.",level:"Coding Problems",difficulty:"Expert",experience:"5-10+ Years",company:["Amazon","Google","Meta"],answer:"Two dicts + doubly linked lists by frequency, plus a minFreq pointer. All operations O(1). Harder than LRU — practice the structure.",tips:"O(1) LFU = frequency buckets of linked lists."},
  {q:"Design Twitter (simplified).",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Meta","Twitter","Amazon"],answer:"Store per-user tweets (id, timestamp). Follow graph. getNewsFeed: heap-merge recent tweets from user + followees. Return top-10 by timestamp.",tips:"Heap-merge for streaming top-K across sources."},
  {q:"Insert Delete GetRandom O(1).",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Google","Amazon","Meta"],answer:"List of values + dict value->index. Delete: swap value with last in list, pop, update dict. getRandom: random.choice on list. All O(1).",tips:"'Swap with last then pop' is the O(1) delete trick."},
  {q:"Number of Subarrays with Sum K.",level:"Coding Problems",difficulty:"Expert",experience:"3-10+ Years",company:["Amazon","Google","Meta"],answer:"Prefix sum + hashmap counting seen prefix sums. For each prefix sum s, add count of (s-k) seen so far. O(n).",code:`def cnt(a,k):\n    seen={0:1}; s=res=0\n    for x in a:\n        s+=x; res+=seen.get(s-k,0); seen[s]=seen.get(s,0)+1\n    return res\nprint(cnt([1,1,1],2))`,output:`2`,tips:"Prefix sum + hashmap = O(n) for sum-related subarray problems."},
  {q:"Maximum Frequency Stack.",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Google","Meta","Amazon"],answer:"Dict of value->freq, and dict of freq->stack of values. push/pop are O(1). Track maxFreq counter.",tips:"Frequency-indexed stacks give O(1) operations."},
  {q:"Reconstruct Itinerary (Eulerian path).",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Google","Amazon","Meta"],answer:"Build graph. Hierholzer's algorithm: DFS greedily using smallest-airport-first; append to result on backtrack; reverse at end.",tips:"Hierholzer's algorithm — worth remembering by name."},
  {q:"Basic Calculator (with +, -, parens).",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Google","Meta","Amazon"],answer:"Stack of signs + partial results. Parens push current state, then pop to combine. O(n).",tips:"Stack of state at each '(' is the trick."},
  {q:"Decode String (like 3[a2[b]] -> abbabbabb).",level:"Coding Problems",difficulty:"Expert",experience:"3-8 Years",company:["Google","Meta"],answer:"Stack of (repeat, prevString). On '[' push, on ']' pop and multiply. Build current string char-by-char.",tips:"Two stacks (or stack of tuples) handles nested brackets."},
  {q:"Robot Room Cleaner (backtracking with unknown grid).",level:"Coding Problems",difficulty:"Expert",experience:"5-10+ Years",company:["Google","Meta","Amazon"],answer:"DFS with 'backtrack' move (turn around, move, turn around) to restore position. Track visited by absolute coordinates.",tips:"'Backtrack physically' is the key move."},
  {q:"Median of Two Sorted Arrays.",level:"Coding Problems",difficulty:"Expert",experience:"5-10+ Years",company:["Google","Amazon","Meta"],answer:"Binary search partition on the smaller array: find i,j such that left halves total (m+n+1)/2 and max(left) <= min(right). O(log(min(m,n))).",tips:"Classic hard problem — the O(log) partition approach is elegant."},
  {q:"Trapping Rain Water II (2D).",level:"Coding Problems",difficulty:"Expert",experience:"5-10+ Years",company:["Google","Amazon","Meta"],answer:"Min-heap of boundary cells. Pop lowest boundary; water trapped in neighbor = max(0, boundary_height - neighbor). Push neighbor with new height.",tips:"2D version uses a heap on the boundary."},
  {q:"Concatenated Words.",level:"Coding Problems",difficulty:"Expert",experience:"4-10+ Years",company:["Amazon","Meta","Google"],answer:"For each word, DP word-break check using OTHER words as dictionary. Sort by length ascending; a word only counts if concatenatable from strictly shorter ones.",tips:"Word break + iterate by length."},
  {q:"Random Pick with Weight.",level:"Coding Problems",difficulty:"Advanced",experience:"3-8 Years",company:["Amazon","Google","Meta"],answer:"Precompute prefix sums. random() * total gives target; binary search in prefix sums finds the index. O(log n) per pick.",tips:"Prefix sum + binary search — weighted sampling classic."},
  {q:"Sliding Puzzle (BFS on states).",level:"Coding Problems",difficulty:"Expert",experience:"5-10+ Years",company:["Google","Meta"],answer:"State = current board tuple. BFS from start; neighbors = boards after swapping 0 with an adjacent cell. Return steps to goal state.",tips:"State-space BFS — 'shortest transformation' pattern."}
);
